    return floor(v) - 4 * floor(v / 4) == 0 and not has_lock() and gold() >= 10

@gene("a11", "next shard to buy: half treasure strength, half the rest jungle health, then power strength/health (intel: Treasure shards go to one carrier until its emblem (5 matching shards, +20% gold) is complete; real b5: our ~10 Treasure shards were spread over ~4 champions and no emblem was ever made)", parents=["a11"])
def next_shard() -> Num:
    d = shards_done()
    if treas_carrier() and items_owned(19) == 0:
        return 18
    if d < shard_until(1):
        return (18 if treas_carrier() else 28)
    if d < shard_until(2):
        return 28
    if d < shard_until(3):
        return 6
    if d < shard_until(4):
        return 10
    return -1


@gene("i17", "this champion carries the team's Treasure: our Vesper Vale, or without one the champion with the lowest type id (intel)")
def treas_carrier() -> Bool:
    if me().type == VESPER_VALE:
        return True
    if any(a.type == VESPER_VALE for a in allies()):
        return False
    return not any(a.type < me().type for a in allies())


@gene("a14", "shards bought this turn (30 gold each)")
def shards_done() -> Num:
    return max(0, -floor(-(SHOP_GOLD - gold()) / 30))

@gene("a15", "shards of the first k kinds in the turn's split (of the shards SHOP_GOLD pays for)")
def shard_until(k: Num) -> Num:
    n = floor(SHOP_GOLD / 30)
    t = floor(n / 2)
    j = floor((n - t) / 2)
    s = floor((n - t - j) / 2)
    if k == 1:
        return t
    if k == 2:
        return t + j
    if k == 3:
        return t + j + s
    return n

@gene("a16", "units of the next shard still to buy")
def shard_left() -> Num:
    d = shards_done()
    for k in range(4):
        if d < shard_until(k + 1):
            return shard_until(k + 1) - d
    return 0

@gene("s1", "my tile")
def here() -> Tile:
