    if d < shard_until(1):
        return 18
    if d < shard_until(2):
        return 28
    if d < shard_until(3):
        return 6
    if d < shard_until(4):
        return 10
    return -1

@gene("a14", "shards bought this turn (30 gold each)")
def shards_done() -> Num:
